window.CODEX_PACKS["taldorei"] = {
  meta: {"id": "taldorei", "label": "Tal'Dorei Campaign Setting", "group": "Green Ronin", "badge": "TD", "edition": "5e-2014"},
  data: {"monsters":[{"name":"Firetamer","slug":"firetamer","size":"Medium","type":"Humanoid","subtype":"any race","group":"Elemental Wardens","alignment":"neutral good","cr":"7","crNum":7.0,"hp":92,"hitDice":"16d8+20","ac":17,"armorDesc":"red dragon scale mail","speed":{"walk":30},"stats":{"str":8,"dex":15,"con":14,"int":12,"wis":18,"cha":11},"saves":{},"perception":null,"skills":{},"vulnerabilities":"","resistances":"fire","immunities":"","conditionImmunities":"","senses":"passive Perception 14","languages":"Common, Druidic, Primordial (Ignan)","actions":[{"name":"Scimitar","desc":"Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 5 (1d6 + 2) slashing damage plus 14 (4d6) fire damage. Flamecharm (Recharges after a Short or Long Rest). The firetamer can cast dominate monster (save DC 16) on a fire elemental or other fire elemental creature. If the elemental has 150 or more hit points, it has advantage on the saving throw.","attack_bonus":6,"damage_dice":"1d6+4d6","damage_bonus":2},{"name":"Flamecharm (Recharges after a Short or Long Rest)","desc":"The firetamer can cast _dominate monster_ (save DC 16) on a fire elemental or other fire elemental creature. If the elemental has 150 or more hit points, it has advantage on the saving throw."}],"bonusActions":[],"reactions":[],"legendaryDesc":"","legendaryActions":[],"specialAbilities":[{"name":"Flameform","desc":"As a bonus action, the firetamer can transform into a **fire elemental**. While in this form, the firetamer cannot cast spells, but can expend a spell slot as a bonus action to regain 1d8 hit points per level of the spell slot expended. When the firetamer is reduced to 0 hit points, falls unconscious, or dies in this form, it reverts to its humanoid form. It can remain in flameform for up to 5 hours, and can enter flameform twice, regaining expended uses after completing a short or long rest."},{"name":"Spellcasting","desc":"The firetamer is a 9th-level spellcaster. Its spellcasting ability is Wisdom (spell save DC 16, +8 to hit with spell attacks). It has the following druid spells prepared:\n\n* Cantrips (at will): druidcraft, mending, produce flame\n* 1st level (4 slots): cure wounds, faerie fire, longstrider, jump\n* 2nd level (3 slots): flame blade, heat metal, lesser restoration\n* 3rd level (3 slots): daylight, dispel magic, protection from energy\n* 4th level (3 slots): blight, freedom of movement, wall of fire 5th level (1 slot): conjure elemental"}],"spellList":["https://api.open5e.com/v2/spells/druidcraft/","https://api.open5e.com/v2/spells/mending/","https://api.open5e.com/v2/spells/produce-flame/","https://api.open5e.com/v2/spells/cure-wounds/","https://api.open5e.com/v2/spells/faerie-fire/","https://api.open5e.com/v2/spells/longstrider/","https://api.open5e.com/v2/spells/jump/","https://api.open5e.com/v2/spells/flame-blade/","https://api.open5e.com/v2/spells/heat-metal/","https://api.open5e.com/v2/spells/lesser-restoration/","https://api.open5e.com/v2/spells/daylight/","https://api.open5e.com/v2/spells/dispel-magic/","https://api.open5e.com/v2/spells/protection-from-energy/","https://api.open5e.com/v2/spells/blight/","https://api.open5e.com/v2/spells/freedom-of-movement/","https://api.open5e.com/v2/spells/wall-of-fire/","https://api.open5e.com/v2/spells/conjure-elemental/"],"environments":[],"img":"","blurb":"Firetamers are the elite elementalists of the fire elemental wardens, using their attunement to the primordial forces of the world to not just create fire, not just command it, but tame it to their w…","desc":"Firetamers are the elite elementalists of the fire elemental wardens, using their attunement to the primordial forces of the world to not just create fire, not just command it, but tame it to their will. A firetamer is nothing like the manic pyromancers; while the latter recklessly wields fire as a weapon, firetamers use their talent to protect others from fire’s destructive power—or to use that same power to destroy those who threaten their people. Firetamers are almost always accompanied by a salamander, a fire elemental, or a small herd of magma or smoke mephits.","source":"taldorei","pack":"taldorei"},{"name":"Skydancer","slug":"skydancer","size":"Medium","type":"Humanoid","subtype":"any race","group":"Elemental Wardens","alignment":"chaotic neutral","cr":"5","crNum":5.0,"hp":63,"hitDice":"14d8","ac":14,"armorDesc":"","speed":{"walk":30,"fly":60},"stats":{"str":10,"dex":18,"con":10,"int":12,"wis":16,"cha":11},"saves":{"dex":7},"perception":null,"skills":{},"vulnerabilities":"","resistances":"","immunities":"","conditionImmunities":"","senses":"passive Perception 16","languages":"Common, Druidic, Primordial (Auran)","actions":[{"name":"Multiattack","desc":"The skydancer makes two skysail staff attacks."},{"name":"Skysail Staff","desc":"Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 7 (1d6 + 4) bludgeoning damage. If the skydancer makes this attack while flying, the target must make a DC 14 Dexterity saving throw, taking 21 (6d6) lightning damage on a failure or half as much damage on a success.","attack_bonus":7,"damage_dice":"1d6","damage_bonus":4}],"bonusActions":[],"reactions":[{"name":"Slow Fall","desc":"When the skydancer takes falling damage, it may reduce the damage by half."}],"legendaryDesc":"","legendaryActions":[],"specialAbilities":[{"name":"Evasion","desc":"If the skydancer is subjected to an effect that allows it to make a Dexterity saving throw to take only half damage, the skydancer instead takes no damage if it succeeds on the saving throw, and only half damage if it fails."},{"name":"Flyby","desc":"The skydancer doesn’t provoke opportunity attacks when it flies out of an enemy’s reach."},{"name":"Skysail","desc":"The skydancer flies with a special weapon called a _skysail_ (see pg. 45). While the _skysail’s_ wings are extended, the skydancer can cast _levitate_ at will, and can spend an action to cast _fly_ on itself (no concentration required) for up to 1 minute once per day. This use of _fly_ instantly replenishes when in an area of powerful air elemental magic."},{"name":"Spellcasting","desc":"The skydancer is a 3rd-level spellcaster. Its spellcasting ability is Wisdom (spell save DC 14, +6 to hit with spell attacks). It has the following druid spells prepared:\n\n* Cantrips (at will): guidance, shillelagh\n* 1st level (4 slots): fog cloud, entangle, jump\n* 2nd level (2 slots): gust of wind, skywrite"}],"spellList":["https://api.open5e.com/v2/spells/guidance/","https://api.open5e.com/v2/spells/shillelagh/","https://api.open5e.com/v2/spells/fog-cloud/","https://api.open5e.com/v2/spells/entangle/","https://api.open5e.com/v2/spells/jump/","https://api.open5e.com/v2/spells/gust-of-wind/"],"environments":[],"img":"","blurb":"Air elemental warden children learn to fly before they learn to walk, accompanying their parents through the snow-fattened clouds on _skysails_ (see pg.","desc":"Air elemental warden children learn to fly before they learn to walk, accompanying their parents through the snow-fattened clouds on _skysails_ (see pg. 45). While all air wardens love the sensation of flight, few hone their skills as rigorously as the skydancers. These graceful masters of the wind are at once artists, performers, and warriors; they are beloved heroes of their people, both defending them in times of danger and bringing them happiness in times of peace.","source":"taldorei","pack":"taldorei"},{"name":"Stoneguard","slug":"stoneguard","size":"Medium","type":"Humanoid","subtype":"any race","group":"Elemental Wardens","alignment":"lawful neutral","cr":"7","crNum":7.0,"hp":152,"hitDice":"16d8+80","ac":15,"armorDesc":"granite half plate","speed":{"walk":30},"stats":{"str":18,"dex":10,"con":20,"int":10,"wis":14,"cha":9},"saves":{"str":8,"con":9,"wis":6},"perception":null,"skills":{},"vulnerabilities":"","resistances":"","immunities":"","conditionImmunities":"petrified","senses":"tremorsense 30 ft., passive Perception 12","languages":"Common, Druidic, Primordial (Terran)","actions":[{"name":"Multiattack","desc":"The stoneguard makes three granite maul attacks."},{"name":"Granite Maul","desc":"Melee Weapon Attack: +8 to hit, reach 5 ft., one target. Hit: 11 (2d6 + 4) bludgeoning damage. If the attack hits, the stoneguard may also immediately cast _thunderwave_ as a bonus action. This casting uses a spell slot, but no material components.","attack_bonus":8,"damage_dice":"2d6","damage_bonus":4}],"bonusActions":[],"reactions":[{"name":"Sentinel","desc":"When a creature within 5 feet of the stoneguard attacks a target other than the stoneguard, it can make a single attack roll against the attacker."},{"name":"Skin to Stone","desc":"When the stoneguard is attacked, it may gain resistance to bludgeoning, piercing, and slashing damage from nonmagical attacks until the end of the attacker’s turn."}],"legendaryDesc":"","legendaryActions":[],"specialAbilities":[{"name":"Spellcasting","desc":"The stoneguard is a 3rd-level spellcaster. Its spellcasting ability is Wisdom (spell save DC 14, +6 to hit with spell attacks). It has the following druid spells prepared:\n\n* Cantrips (at will): druidcraft, resistance\n* 1st level (4 slots): goodberry, speak with animals, thunderwave\n* 2nd level (2 slots): hold person, spike growth"}],"spellList":["https://api.open5e.com/v2/spells/druidcraft/","https://api.open5e.com/v2/spells/resistance/","https://api.open5e.com/v2/spells/goodberry/","https://api.open5e.com/v2/spells/speak-with-animals/","https://api.open5e.com/v2/spells/thunderwave/","https://api.open5e.com/v2/spells/hold-person/","https://api.open5e.com/v2/spells/spike-growth/"],"environments":[],"img":"","blurb":"The elemental wardens of earth are a stoic people, slow to change socially, and more likely to fight defensive battles and outlast enemies than wage offensive wars.","desc":"The elemental wardens of earth are a stoic people, slow to change socially, and more likely to fight defensive battles and outlast enemies than wage offensive wars. The stoneguard are the perfect embodiment of this ideal; their druidic training has been augmented by ancient combat techniques, allowing them to hold fast against a tide of enemies. They craft arms and armor from the granite around them, and their magical stonecraft rivals that of the dwarves.","source":"taldorei","pack":"taldorei"},{"name":"Waverider","slug":"waverider","size":"Medium","type":"Humanoid","subtype":"any race","group":"Elemental Wardens","alignment":"neutral good","cr":"4","crNum":4.0,"hp":77,"hitDice":"14d8+14","ac":14,"armorDesc":"hide armor of cold resistance","speed":{"walk":30},"stats":{"str":15,"dex":14,"con":12,"int":10,"wis":16,"cha":13},"saves":{"con":4,"wis":6},"perception":null,"skills":{},"vulnerabilities":"","resistances":"cold","immunities":"","conditionImmunities":"","senses":"passive Perception 13","languages":"Common, Druidic, Primordial (Aquan)","actions":[{"name":"Harpoon","desc":"Melee or Ranged Weapon Attack: +5 to hit, reach 5 ft., range 20/60 ft., one target. Hit: 5 (1d6 + 2) piercing damage. Attacks with this weapon while underwater are not made with disadvantage.","attack_bonus":5,"damage_dice":"1d6","damage_bonus":2}],"bonusActions":[],"reactions":[],"legendaryDesc":"","legendaryActions":[],"specialAbilities":[{"name":"Fishform","desc":"As a bonus action, the waverider can transform into a **hunter shark** or **giant octopus**. While in this form, the waverider cannot cast spells, but can expend a spell slot as a bonus action to regain 1d8 hit points per level of the spell slot expended. When the waverider is reduced to 0 hit points, falls unconscious, or dies in this form, it reverts to its humanoid form. It can remain in fishform for up to 3 hours, and can enter fishform twice, regaining expended uses after completing a short or long rest."},{"name":"Healing Tides","desc":"Whenever the waverider casts a spell of 1st level or higher that affects a nonhostile creature, that creature regains 3 hit points (in addition to any healing the spell may provide)."},{"name":"Marine Empathy","desc":"The waverider can speak with and understand aquatic plants and animals."},{"name":"Spellcasting","desc":"The waverider is a 7th-level spellcaster. Its spellcasting ability is Wisdom (spell save DC 14, +6 to hit with spell attacks). It has the following druid spells prepared:\n\n* Cantrips (at will): druidcraft, poison spray, resistance\n* 1st level (4 slots): cure wounds, create or destroy water, healing word\n* 2nd level (3 slots): animal messenger, enhance ability, lesser restoration\n* 3rd level (3 slots): conjure animals (aquatic beasts only), water walk, water breathing\n* 4th level (1 slots): control water"}],"spellList":["https://api.open5e.com/v2/spells/druidcraft/","https://api.open5e.com/v2/spells/poison-spray/","https://api.open5e.com/v2/spells/resistance/","https://api.open5e.com/v2/spells/cure-wounds/","https://api.open5e.com/v2/spells/create-or-destroy-water/","https://api.open5e.com/v2/spells/healing-word/","https://api.open5e.com/v2/spells/animal-messenger/","https://api.open5e.com/v2/spells/enhance-ability/","https://api.open5e.com/v2/spells/lesser-restoration/","https://api.open5e.com/v2/spells/conjure-animals/","https://api.open5e.com/v2/spells/water-walk/","https://api.open5e.com/v2/spells/water-breathing/","https://api.open5e.com/v2/spells/control-water/"],"environments":[],"img":"","blurb":"The waveriders know firsthand the dangers of the open ocean, and dedicate their lives to protecting seafarers from storms, pirates, and sea monsters.","desc":"The waveriders know firsthand the dangers of the open ocean, and dedicate their lives to protecting seafarers from storms, pirates, and sea monsters. Though they are not warriors, they are accomplished healers and aquatic empaths, using their powers to seek out and rescue survivors of marine disasters, sometimes returning critically wounded survivors to the tribe of elemental wardens itself. The isolationists among the water wardens condemn this practice, fearing that the refugees threaten their way of life. The waveriders take their peers’ scorn in stride, for they would rather be righteous than popular.\nA waverider turns to violence only as a last resort, and prefer to fight in fishform than with their fishing harpoon, using hit-and-run tactics as a shark or their octopus form’s natural camouflage to harry opponents. When patrolling the open seas, waveriders skim across the water on personal waveboards with folding sails, similar in function to the _skysails_ of the wind wardens.","source":"taldorei","pack":"taldorei"}],"items":[{"name":"Skysail","rarity":"Rare","attune":true,"attuneDesc":"requires attunement","type":"Wondrous item","blurb":"These bat-like wings affixed to a pole are constructed out of either bone and leather or wood and cloth. While these wings are opened and the rung of the pole stepped into, you can use an action to cast _levitate_ on yo…","desc":"These bat-like wings affixed to a pole are constructed out of either bone and leather or wood and cloth. While these wings are opened and the rung of the pole stepped into, you can use an action to cast _levitate_ on yourself at will.\nAdditionally, you can use an action to cast _fly_ on yourself for up to 1 minute (no concentration required). The _fly_ spell ends if you lose physical contact with the skysail. You cannot use this ability again until you complete a long rest, or you (and the Skysail) are immersed in extremely powerful air elemental magic, such as within the Elemental Plane of Air. When not in use, these wings can be easily folded together and worn beneath a cloak, and the pole used as a quarterstaff.","source":"taldorei","pack":"taldorei"}],"feats":[{"name":"Rapid Drinker","prerequisite":"*N/A*","blurb":"Through a lifestyle of hard, competitive drinking, you’ve learned how to quaff drinks at an incredibly accelerated pace.","desc":"Through a lifestyle of hard, competitive drinking, you’ve learned how to quaff drinks at an incredibly accelerated pace. You gain the following benefits:\n\n• * You can drink a potion as a Bonus action, instead of as an action.\n• * You have advantage on any saving throws triggered by ingesting an alcoholic or dangerous substance.","source":"taldorei","pack":"taldorei"}],"backgrounds":[{"name":"Crime Syndicate Member","skills":["Deception","plus your choice of one between Sleight of Hand or Stealth."],"tools":["Your choice of one from Thieves’ Tools","Forgery Kit","or Disguise Kit."],"languages":"Thieves’ Cant","feature":"A Favor In Turn","blurb":"Whether you grew up in the slum-run streets bamboozling foolish gamblers out of their fortune, or spent your youth pilfering loose coin from the pockets of less-attentive travelers, your lifestyle of…","desc":"Whether you grew up in the slum-run streets bamboozling foolish gamblers out of their fortune, or spent your youth pilfering loose coin from the pockets of less-attentive travelers, your lifestyle of deceiving-to-survive eventually drew the attention of an organized and dangerous crime syndicate. Offering protection, a modicum of kinship, and a number of useful resources to further develop your craft as a criminal, you agree to receive the syndicate’s brand and join their ranks.\nYou might have been working the guild’s lower ranks, wandering the alleys as a simple cutpurse to fill the meager coffers with wayward gold until the opportunity arose to climb the professional ladder. Or you may have become a clever actor and liar whose skill in blending in with all facets of society has made you an indispensable agent of information gathering. Perhaps your technique with a blade and swiftness of action led you to become a feared hitman for a syndicate boss, sending you on the occasional contract to snuff the life of some unfortunate soul who crossed them. Regardless, while the threat of the law is ever looming, the advantages to having a foot in such a powerful cartel can greatly outweigh the paranoia.","source":"taldorei","pack":"taldorei"},{"name":"Elemental Warden","skills":["Nature","plus your choice of one between Arcana or Survival."],"tools":["Herbalism Kit"],"languages":"One of your choice.","feature":"Elemental Harmony","blurb":"Away from the complex political struggles of the massive cities, you’ve instead been raised to revere and uphold the protection of the natural world, while policing, bending, and guiding the elementa…","desc":"Away from the complex political struggles of the massive cities, you’ve instead been raised to revere and uphold the protection of the natural world, while policing, bending, and guiding the elemental powers that either foster life or destroy it. Living among smaller bands of tribal societies means you have stronger ties to your neigh- bors than most, and the protection of this way of life is of cardinal importance. Each elemental warden is tethered to one of the four elemental tribes and their villages. You must select one: Fire, Water, Earth, or Wind.\nYour upbringing may have prepared you to be a fierce warrior, trained in combat to defend your culture and charge as protectors of the rifts. It’s possible your meditation on the balance of the elements has brought you peace of mind with strength of body as a monk. Perhaps you found strength in bending the elements yourself, joining the ranks of the powerful elemental druids. Regardless, your loyalties ultimately lie with the continued safety of your tribe, and you’ve set out to gather allies to your cause and learn more about the world around you.","source":"taldorei","pack":"taldorei"},{"name":"Fate-Touched","skills":[],"tools":[],"languages":"","feature":"Fortune’s Grace","blurb":"Many lives and many souls find their ways through the patterns of fate and destiny, their threads following the path meant for them, oblivious and eager to be a part of the woven essence of history m…","desc":"Many lives and many souls find their ways through the patterns of fate and destiny, their threads following the path meant for them, oblivious and eager to be a part of the woven essence of history meant for them. Some souls, however, glide forth with mysterious influence, their threads bending the weave around them, toward them, unknowingly guiding history itself wherever they walk. Events both magnificent and catastrophic tend to follow such individuals. These souls often become great rulers and terrible tyrants, powerful mages, religious leaders, and legendary heroes of lore. These are the fate-touched.\nFew fate-touched ever become aware of their prominent nature. Outside of powerful divination magics, it’s extremely difficult to confirm one as fate-touched. There are many communities that regard the status as a terrible omen, treating a confirmed fate-touched with mistrust and fear. Others seek them as a blessing, rallying around them for guidance. Some of renown and power grow jealous, wishing to bend a fate-touched beneath their will, and some stories speak of mages of old attempting to extract or transfer the essence itself.\nPlayers are not intended to select this background, but this is instead provided for the dungeon master to consider for one or more of their players, or perhaps a prominent NPC, as their campaign unfolds. It provides very minor mechanical benefit, but instead adds an element of lore, importance, and fate-bearing responsibility to a character within your story. Being fate-touched overlaps and co-exists with the character’s current background, only adding to their mystique. Consider it for a player character who would benefit from being put more central to the coming conflicts of your adventure, or for an NPC who may require protection as they come into their destiny. Perhaps consider a powerful villain discovering their fate-twisting nature and using it to wreak havoc. All of these possibilities and more can be explored should you choose to include a fate-touched within your campaign.","source":"taldorei","pack":"taldorei"},{"name":"Lyceum Student","skills":["Your choice of two from among Arcana","History","and Persuasion."],"tools":[],"languages":"Two of your choice","feature":"Student Privilege","blurb":"You most likely came up through money or a family of social prestige somewhere in the world, as tuition at a lyceum is not inexpensive.","desc":"You most likely came up through money or a family of social prestige somewhere in the world, as tuition at a lyceum is not inexpensive. Your interests and pursuits have brought you to the glittering halls of a place of learning, soaking in all and every lesson you can to better make your mark on the world (or at least you should be, but every class has its slackers). However, the call to adventure threatens to pull you from your studies, and now the challenge of balancing your education with the tide of destiny sweeping you away is looming.\nYou may have come to better research and understand the history and lore of the lands you now call home, perhaps seeking a future here at the lyceum as a professor. You could also have been drawn by the promise of prosperity in politics, learning the inner workings of government and alliances to better position yourself as a future writer of history. Perhaps you’ve discovered a knack for the arcane, coming here to focus on refining your spellcraft in the footsteps of some of the finest wizards and sorcerers in days of yore.","source":"taldorei","pack":"taldorei"},{"name":"Recovered Cultist","skills":["Religion and Deception."],"tools":[],"languages":"One of your choice.","feature":"Wicked Awareness","blurb":"The rise of cults are scattered and separated, with little to no unity between the greater evils.","desc":"The rise of cults are scattered and separated, with little to no unity between the greater evils. Hidden hierarchies of power-hungry mortals corrupt and seduce, promising a sliver of the same power they had been promised when the time comes to reap their harvest.\nYou once belonged to such a cult. Perhaps it was brief, embracing the rebellious spirit of youth and curious where this path may take you. You also may have felt alone and lost, this community offering a welcome you had been subconsciously seeking. It’s possible you were raised from the beginning to pray to the gods of shadow and death. Then one day the veil was lifted and the cruel truth shook your faith, sending you running from the false promises and seeking redemption.\nYou have been freed from the bindings of these dangerous philosophies, but few secret societies find comfort until those who abandon their way are rotting beneath the soil.","source":"taldorei","pack":"taldorei"}],"classes":[{"name":"Blood Domain","subclassOf":"Cleric","hd":null,"primary":[],"saves":[],"armor":[],"weapons":[],"equipment":[],"blurb":"The Blood domain centers around the understanding of the natural life force within one’s own physical body.","features":[{"lvl":1,"name":"Blood Domain Spells (table)","text":"Cleric Level | Spells                                | \r\n |--------------|-------------------------------------------| \r\n | 1st          | *sleep*, *ray of sickness*                | \r\n | 3rd          | *ray of enfeeblement*, *crown of madness* | \r\n | 5th          | *haste*, *slow*                           | \r\n | 7th          | *blight*, *stoneskin*                     | \r\n | 9th          | *dominate person*, *hold monster*         |"},{"lvl":1,"name":"Bloodletting Focus","text":"From 1st level, your divine magics draw the blood from inflicted wounds, worsening the agony of your nearby foes. When you use a spell of 1st level or higher to damage to any creatures that have blood, those creatures suffer additional necrotic damage equal to 2 + the spell’s level."},{"lvl":1,"name":"Bonus Proficiencies","text":"At 1st Level, you gain proficiency with martial weapons."},{"lvl":2,"name":"Channel Divinity: Blood Puppet","text":"Starting at 2nd level, you can use your Channel Divinity to briefly control a creature’s actions against their will. As an action, you target a Large or smaller creature that has blood within 60 feet of you. That creature must succeed on a Constitution saving throw against your spell save DC or immediately move up to half of their movement in any direction of your choice and make a single weapon attack against a creature of your choice within range. Dead or unconscious creatures automatically fail their saving throw. At 8th level, you can target a Huge or smaller creature."},{"lvl":6,"name":"Channel Divinity: Crimson Bond","text":"Starting at 6th level, you can use your Channel Divinity to focus on a sample of blood from a creature that is at least 2 ounces, and that has been spilt no longer than a week ago. As an action, you can focus on the blood of the creature to form a bond and gain information about their current circumstances. You know their approximate distance and direction from you, as well as their general state of health, as long as they are within 10 miles of you. You can maintain Concentration on this bond for up to 1 hour.\nDuring your bond, you can spend an action to attempt to connect with the bonded creature’s senses. The target makes a Constitution saving throw against your spell save DC. If they succeed, the connection is resisted, ending the bond. You suffer 2d6 necrotic damage. Upon a failed saving throw, you can choose to either see through the eyes of or hear through their ears of the target for a number of rounds equal to your Wisdom modifier (minimum of 1). During this time, you are blind or deaf (respectively) with regard to your own senses. Once this connection ends, the Crimson Bond is lost.\n\n **Health State Examples**\n\n| 100%    | Untouched            |\r\n| 99%-50% | Injured              |\r\n| 49%-1%  | Heavily Wounded      |\r\n| 0%      | Unconscious or Dying |\r\n| –       | Dead                 |"},{"lvl":8,"name":"Sanguine Recall","text":"At 8th level, you can sacrifice a portion of your own vitality to recover expended spell slots. As an action, you recover spell slots that have a combined level equal to or less than half of your cleric level (rounded up), and none of the slots can be 6th level or higher. You immediately suffer 1d6 damage per spell slot level recovered. You can’t use this feature again until you finish a long rest.\nFor example, if you’re a 4th-level Cleric, you can recover up to two levels of spell slots. You can recover either a 2nd-level spell slot or two 1st-level spell slots. You then suffer 2d6 damage."},{"lvl":17,"name":"Vascular Corruption Aura","text":"At 17th level, you can emit a powerful aura as an action that extends 30 feet out from you that pulses necrotic energy through the veins of nearby foes, causing them to burst and bleed. For 1 minute, any enemy creatures with blood that begin their turn within the aura or enter it for the first time on their turn immediately suffer 2d6 necrotic damage. Any enemy creature with blood that would regain hit points while within the aura only regains half of the intended number of hit points (rounded up).\nOnce you use this feature, you can’t use it again until you finish a long rest."}],"subclasses":[],"source":"tdcs","pack":"taldorei"},{"name":"Path of the Juggernaut","subclassOf":"Barbarian","hd":null,"primary":[],"saves":[],"armor":[],"weapons":[],"equipment":[],"blurb":"Honed to assault the lairs of powerful threats to their way of life, or defend against armed hordes of snarling goblinoids, the juggernauts represent the finest of frontline destroyers within the pri…","features":[{"lvl":3,"name":"Stance of the Mountain","text":"You harness your fury to anchor your feet to the earth, shrugging off the blows of those who wish to topple you. Upon choosing this path at 3rd level, you cannot be knocked prone while raging unless you become unconscious."},{"lvl":3,"name":"Thunderous Blows","text":"Starting when you choose this path at 3rd level, your rage instills you with the strength to batter around your foes, making any battlefield your domain. Once per turn while raging, when you damage a creature with a melee attack, you can force the target to make a Strength saving throw (DC 8 + your proficiency bonus + your Strength modifier). On a failure, you push the target 5 feet away from you, and you can choose to immediately move 5 feet into the target’s previous position."},{"lvl":6,"name":"Demolishing Might","text":"Beginning at 6th level, you can muster destructive force with your assault, shaking the core of even the strongest structures. All of your melee attacks gain the siege property (your attacks deal double damage to objects and structures). Your melee attacks against creatures of the construct type deal an additional 1d8 weapon damage."},{"lvl":10,"name":"Overwhelming Cleave","text":"Upon reaching 10th level, you wade into armies of foes, great swings of your weapon striking many who threaten you. When you make a weapon attack while raging, you can make another attack as a bonus action with the same weapon against a different creature that is within 5 feet of the original target and within range of your weapon."},{"lvl":14,"name":"Unstoppable","text":"Starting at 14th level, you can become “unstoppable” when you rage. If you do so, for the duration of the rage your speed cannot be reduced, and you are immune to the frightened, paralyzed, and stunned conditions. If you are frightened, paralyzed, or stunned, you can still take your bonus action to enter your rage and suspend the effects for the duration of the rage. When your rage ends, you suffer one level of exhaustion (as described in appendix A, PHB)."}],"subclasses":[],"source":"tdcs","pack":"taldorei"},{"name":"Runechild","subclassOf":"Sorcerer","hd":null,"primary":[],"saves":[],"armor":[],"weapons":[],"equipment":[],"blurb":"The weave and flow of magic is mysterious and feared by many.","features":[{"lvl":1,"name":"Essence Runes","text":"At 1st level, your body has begun to express your innate magical energies as natural runes that hide beneath your skin. You begin with 1 Essence Rune, and gain an addi- tional rune whenever you gain a level in this class. Runes can manifest anywhere on your body, though the first usually manifests on the forehead. They remain invisible when inert.\nAt the end of a turn where you spent any number of sorcery points for any of your class features, an equal number of essence runes glow with stored energy, becoming charged runes. If you expend a charged rune to use one of your Runechild features, it returns to being an inert essence rune.\nAs a bonus action, you may spend any number of sorcery points to convert an equal number of essence runes into charged runes. If you have no sorcery points and no charged runes, you can convert a single essence rune into a charged rune as an action\nIf you have 5 or more charged runes, you emit bright light in a 5 foot radius and dim light for an additional 5 feet. Any charged runes revert to inert essence runes after you complete a long rest."},{"lvl":1,"name":"Glyphs of Aegis","text":"Beginning at 1st level, you can release the stored arcane power within your runes to absorb or deflect threatening attacks against you. Whenever you take damage from an attack, hazard, or spell, you can use a reaction to expend any number of charged runes, rolling 1d6 per charged rune. You subtract the total rolled from the damage inflicted by the attack, hazard, or spell.\nAt 6th level, you can use an action to expend a charged rune, temporarily transferring a Glyph of Aegis to a creature you touch. A creature can only hold a single glyph, and it lasts for 1 hour, or until the creature is damaged by an attack, hazard, or spell. The next time that creature takes damage from any of those sources, roll 1d6 and subtract the number rolled from the damage roll. The glyph is then lost."},{"lvl":6,"name":"Manifest Inscriptions","text":"At 6th level, you can reveal hidden glyphs and enchantments that surround you. As an action, you can expend a charged rune to cause any hidden magical marks, runes, wards, or glyphs within 15 feet of you to reveal themselves with a glow for 1 round. This glow is considered dim light for a 5 foot radius around the mark or glyph."},{"lvl":6,"name":"Sigilic Augmentation","text":"Upon reaching 6th level, you can channel your runes to temporarily bolster your physical capabilities. You can expend a charged rune as a bonus action to enhance either your Strength, Dexterity, or Constitution, granting you advantage on ability checks with the chosen ability score until the start of your next turn. You can choose to main- tain this benefit additional rounds by expending a charged rune at the start of each of your following turns."},{"lvl":14,"name":"Runic Torrent","text":"Upon reaching 14th level, you can channel your stored runic energy to instill your spells with overwhelming arcane power, bypassing even the staunchest defenses. Whenever you cast a spell, you can expend a number of charged runes equal to the spell’s level to allow it to ignore any resistance or immunity to the spell’s damage type the targets may have."},{"lvl":18,"name":"Arcane Exemplar Form","text":"Beginning at 18th level, you can use a bonus action and expend 6 or more charged runes to temporarily become a being of pure magical energy. This new form lasts for 3 rounds plus 1 round for each charged rune expended over 6. While you are in your exemplar form, you gain the following benefits: \n* You have a flying speed of 40 feet. \n* Your spell save DC is increased by 2. \n* You have resistance to damage from spells. \n* When you cast a spell of 1st level or higher, you regain hit points equal to the spell’s level. When your Arcane Exemplar form ends, you can’t move or take actions until after your next turn, as your body recovers from the transformation. Once you use this feature, you must finish a long rest before you can use it again."}],"subclasses":[],"source":"tdcs","pack":"taldorei"},{"name":"Way of the Cerulean Spirit","subclassOf":"Monk","hd":null,"primary":[],"saves":[],"armor":[],"weapons":[],"equipment":[],"blurb":"To become a Cerulean Spirit is to give one’s self to the quest for unveiling life’s mysteries, bringing light to the secrets of the dark, and guarding the most powerful and dangerous of truths from t…","features":[{"lvl":3,"name":"Extract Aspects","text":"Beginning at 3rd level when choosing this tradition, when you pummel an opponent and connect with multiple pressure points, you can extract crucial information about your foe. Whenever you hit a single creature with two or more attacks in one round, you can spend 1 ki point to force the target to make a Constitution saving throw. On a failure, you learn one aspect about the creature of your choice: Creature Type, Armor Class, Senses, Highest Saving Throw Modifier, Lowest Saving Throw Modifier, Damage Vulnerabilities, Damage Resistances, Damage Immunities, or Condition Immunities.\nUpon reaching 6th level, if the target fails their saving throw, you can choose two aspects to learn. This increases to three aspects at 11th level, and four aspects at 17th level."},{"lvl":3,"name":"Mystical Erudition","text":"Upon choosing this tradition at 3rd level, you’ve undergone extensive training with the Cerulean Spirit, allowing you to mystically recall information on history and lore from the monastery’s collected volumes. Whenever you make an Intelligence (Arcana), Intelligence (History), or Intelligence (Religion) check, you can spend 1 ki point to gain advantage on the roll.\nIn addition, you learn one language of your choice. You gain additional languages at 11th and 17th level."},{"lvl":6,"name":"Extort Truth","text":"At 6th level, you can hit a series of hidden nerves on a creature with precision, temporarily causing them to be unable to mask their true thoughts and intent. If you manage to hit a single creature with two or more attacks in one round, you can spend 2 ki points to force them to make a Charisma saving throw. You can choose to have these attacks deal no damage. On a failed save, the creature is unable to speak a deliberate lie for 1 minute. You know if they succeeded or failed on their saving throw.\nAn affected creature is aware of the effect and can thus avoid answering questions to which it would normally respond with a lie. Such a creature can be evasive in its answers as long as the effect lasts."},{"lvl":6,"name":"Mind of Mercury","text":"Starting at 6th level, you’ve honed your awareness and reflexes through mental aptitude and pattern recognition. You can take a number of additional reactions each round equal to your Intelligence modifier (minimum of 1), at the cost of 1 ki point per reaction beyond the first. You can only use one reaction per trigger.\nIn addition, whenever you make an Intelligence (Investigation) check, you can spend 1 ki point to gain advantage on the roll."},{"lvl":11,"name":"Preternatural Counter","text":"Beginning at 11th level, your quick mind and study of your foe allows you to use their failure to your advantage. If a creature misses you with an attack, you can immediately use your reaction to make a melee attack against that creature."},{"lvl":17,"name":"Debilitating Barrage","text":"Upon reaching 17th level, you’ve gained the knowledge to temporarily alter and lower a creature’s fortitude by striking a series of pressure points. Whenever you hit a single creature with three or more attacks in one round, you can spend 3 ki points to give the creature disadvantage to their attack rolls until the end of your next turn, and they must make a Constitution saving throw. On a failure, the creature suffers vulnerability to a damage type of your choice for 1 minute, or until after they take any damage of that type.\nCreatures with resistance or immunity to the chosen damage type do not suffer this vulnerability, which is revealed after the damage type is chosen. You can select the damage type from the following list: acid, bludgeoning, cold, fire, force, lightning, necrotic, piercing, poison, psychic, radiant, slashing, thunder."}],"subclasses":[],"source":"tdcs","pack":"taldorei"}]}
};
